@Transactional(readOnly = true)
    public ContractDtos.SummaryResponse summary(String userId, String range, LocalDate from, LocalDate to, String accountId) {
        LocalDate[] window = resolveWindow(range, from, to);
        from = window[0]; to = window[1];
        UUID uuid = UUID.fromString(userId);
        String currency = profileRepo.getUserCurrency(uuid);

        Object[] row = movementRepo.getSummary(uuid, from, to, toUuid(accountId));

        BigDecimal income = toBigDecimal(row[0]), expenses = toBigDecimal(row[1]);
        BigDecimal debtPayments = toBigDecimal(row[2]), fixedPayments = toBigDecimal(row[3]);
        BigDecimal availableBalance = accountId == null ? 
            accountRepo.getTotalBalance(uuid) : 
            accountRepo.getAccountBalance(uuid, UUID.fromString(accountId));
        return new ContractDtos.SummaryResponse(income, expenses, fixedPayments, debtPayments, availableBalance, currency);
    }

public FinanceApiService(ProfileRepository profileRepo, CategoryRepository categoryRepo,
                            AccountRepository accountRepo, MovementRepository movementRepo,
                            DebtRepository debtRepo, ScheduledPaymentRepository scheduledPaymentRepo,
                            SupabaseAuthClient authClient, ObjectMapper objectMapper) {
        this.profileRepo = profileRepo;
        this.categoryRepo = categoryRepo;
        this.accountRepo = accountRepo;
        this.movementRepo = movementRepo;
        this.debtRepo = debtRepo;
        this.scheduledPaymentRepo = scheduledPaymentRepo;
        this.authClient = authClient;
        this.objectMapper = objectMapper;
    }

private ContractDtos.MeResponse mapToMeResponse(Object[] row) {
        Map<String, Object> map = new LinkedHashMap<>();
        map.put("userId", row[0]);
        map.put("id", row[1]);
        map.put("displayName", row[2]);
        map.put("currency", row[3]);
        map.put("payCycle", row[4]);
        map.put("payDays", normalizePayDays(row[5]));
        map.put("createdAt", row[6]);
        map.put("updatedAt", row[7]);
        map.put("deletedAt", row[8]);
        map.put("syncStatus", row[9]);
        map.put("version", row[10]);
        return objectMapper.convertValue(map, ContractDtos.MeResponse.class);
    }

