public ContractDtos.AccountResponse updateAccount(String userId, String id, ContractDtos.UpsertAccountRequest request) {
        UUID userUuid = UUID.fromString(userId);
        UUID accountUuid = UUID.fromString(id);
        if (accountRepo.existsByUserAndId(accountUuid, userUuid) == 0)
            throw new ApiException(HttpStatus.NOT_FOUND, "account not found");
        Object[] row = accountRepo.updateAccount(accountUuid, userUuid, request.name(), request.type(),
            request.institution(), request.balance(), request.creditLimit(), request.closingDay(),
            request.dueDay(), request.active(), request.currency(), request.currency());
        return mapToAccountResponse(row);
    }

private ContractDtos.AccountResponse mapToAccountResponse(Object[] row) {
        return new ContractDtos.AccountResponse(
            toString(row[0]), toString(row[1]), toString(row[2]), toString(row[3]),
            toString(row[4]), toString(row[5]), toBigDecimal(row[6]), toBigDecimal(row[7]),
            toInteger(row[8]), toInteger(row[9]), toBoolean(row[10]),
            toInstant(row[11]), toInstant(row[12]), toInstant(row[13]),
            toSyncStatus(row[14]), toLong(row[15], 1L)
        );
    }

private ContractDtos.DebtResponse mapToDebtResponse(Object[] row) {
        return new ContractDtos.DebtResponse(
            toString(row[0]), toString(row[1]), toString(row[2]),
            toBigDecimal(row[3]), toBigDecimal(row[4]), toString(row[5]),
            toLocalDate(row[6]), toString(row[7]),
            toInstant(row[8]), toInstant(row[9]), toInstant(row[10]),
            toSyncStatus(row[11]), toLong(row[12], 1L)
        );
    }

@Transactional(readOnly = true)
    public List<ContractDtos.CategoryStatResponse> categoryStats(String userId, String range, LocalDate from, LocalDate to, String accountId) {
        LocalDate[] window = resolveWindow(range, from, to);
        from = window[0]; to = window[1];
        UUID uuid = UUID.fromString(userId);

        List<Object[]> rows = movementRepo.getCategoryStats(uuid, from, to, toUuid(accountId));
        List<ContractDtos.CategoryStatResponse> raw = rows.stream()
            .map(r -> new ContractDtos.CategoryStatResponse(toString(r[0]), toString(r[1]), toBigDecimal(r[2]), BigDecimal.ZERO))
            .collect(Collectors.toList());
        BigDecimal total = raw.stream().map(ContractDtos.CategoryStatResponse::amount).reduce(BigDecimal.ZERO, BigDecimal::add);
        return raw.stream().map(item -> {
            BigDecimal pct = total.signum() == 0 ? BigDecimal.ZERO : item.amount().multiply(BigDecimal.valueOf(100)).divide(total, 2, java.math.RoundingMode.HALF_UP);
            return new ContractDtos.CategoryStatResponse(item.categoryId(), item.categoryName(), item.amount(), pct);
        }).collect(Collectors.toList());
    }

