        items.addAll(debtRepo.getUpcomingDebts(uuid).stream()
            .map(r -> new ContractDtos.UpcomingItemResponse(toString(r[0]), toString(r[1]), toString(r[2]), toLocalDate(r[3]), toBigDecimal(r[4])))
