public class SecurityConfig {

    @Bean
    SecurityFilterChain filterChain(HttpSecurity http, JwtDecoder jwtDecoder) throws Exception {
        return http
                .csrf(AbstractHttpConfigurer::disable)
                .authorizeHttpRequests(auth -> auth
                        .requestMatchers("/auth/**", "/actuator/health").permitAll()
                        .anyRequest().authenticated())
                .oauth2ResourceServer(oauth -> oauth.jwt(jwt -> jwt.decoder(jwtDecoder)))
                .build();
    }

    @Bean
    JwtDecoder jwtDecoder(AppProperties properties) {
        return NimbusJwtDecoder.withJwkSetUri(properties.jwkSetUri())
                .jwsAlgorithm(SignatureAlgorithm.ES256)
                .build();
    }
}

@RestControllerAdvice
public class GlobalExceptionHandler {

    @ExceptionHandler(ApiException.class)
    public ResponseEntity<Map<String, Object>> handleApi(ApiException ex) {
        return ResponseEntity.status(ex.getStatus()).body(errorBody(ex.getMessage(), null));
    }

    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ResponseEntity<Map<String, Object>> handleValidation(MethodArgumentNotValidException ex) {
        Map<String, String> fields = new LinkedHashMap<>();
        ex.getBindingResult().getFieldErrors().forEach(err -> fields.put(err.getField(), err.getDefaultMessage()));
        return ResponseEntity.badRequest().body(Map.of(
                "error", "validation_failed",
                "fields", fields
        ));
    }

    @ExceptionHandler(MethodArgumentTypeMismatchException.class)
    public ResponseEntity<Map<String, Object>> handleTypeMismatch(MethodArgumentTypeMismatchException ex) {
        String paramName = ex.getName() != null ? ex.getName() : "unknown";
        Object paramValue = ex.getValue() != null ? ex.getValue() : "null";
        return ResponseEntity.badRequest().body(errorBody(
            "invalid_parameter",
            "Invalid value '" + paramValue + "' for parameter '" + paramName + "'. " +
            "Expected type: " + (ex.getRequiredType() != null ? ex.getRequiredType().getSimpleName() : "unknown")
        ));
    }

    @ExceptionHandler(Exception.class)
    public ResponseEntity<Map<String, Object>> handleOther(Exception ex) {
        return ResponseEntity.internalServerError().body(errorBody("internal_error", ex.getMessage()));
    }

    private Map<String, Object> errorBody(String error, String message) {
        Map<String, Object> body = new LinkedHashMap<>();
        body.put("error", error == null ? "internal_error" : error);
        if (message != null && !message.isBlank()) {
            body.put("message", message);
        }
        return body;
    }
}

@Component
public class FinanceMapper {

    private final ObjectMapper objectMapper;

    public FinanceMapper(ObjectMapper objectMapper) {
        this.objectMapper = objectMapper;
    }

    // ==================== MAPPERS PRINCIPALES ====================

    public ContractDtos.MeResponse mapToMeResponse(Object[] row) {
        row = unwrap(row);
        Map<String, Object> map = new LinkedHashMap<>();
        map.put("userId",      toStringText(row[0]));
        map.put("id",          toStringText(row[1]));
        map.put("displayName", toStringText(row[2]));
        map.put("currency",    toStringText(row[3]));
        map.put("payCycle",    toStringText(row[4]));
        map.put("payDays",     normalizePayDays(row[5]));
        map.put("createdAt",   row[6]);
        map.put("updatedAt",   row[7]);
        map.put("deletedAt",   row[8]);
        map.put("syncStatus",  toStringText(row[9]));
        map.put("version",     row[10]);
        return objectMapper.convertValue(map, ContractDtos.MeResponse.class);
    }

    public ContractDtos.CategoryResponse mapToCategoryResponse(Object[] row) {
    	row = unwrap(row);
        return new ContractDtos.CategoryResponse(
            toString(row[0]), toString(row[1]), toString(row[2]), toString(row[3]),
            toString(row[4]), toString(row[5]),
            toInstant(row[6]), toInstant(row[7]), toInstant(row[8]),
            toSyncStatus(row[9]), toLong(row[10], 1L)
        );
    }

    // Para listAccounts y createAccount (16 columnas - incluye currency)
    public ContractDtos.AccountResponse mapToAccountResponse(Object[] row) {
        row = unwrap(row);
        return new ContractDtos.AccountResponse(
            toString(row[0]),     // id
            toString(row[1]),     // userId
            toString(row[2]),     // type (account_type)
            toString(row[3]),     // name
            toString(row[4]),     // institution (bank_name)
            toString(row[5]),     // currency
            toBigDecimal(row[6]), // balance
            toBigDecimal(row[7]), // creditLimit
            toInteger(row[8]),    // closingDay
            toInteger(row[9]),    // dueDay
            toBoolean(row[10]),   // active
            toInstant(row[11]),   // createdAt
            toInstant(row[12]),   // updatedAt
            toInstant(row[13]),   // deletedAt
            toSyncStatus(row[14]), // syncStatus
            toLong(row[15], 1L)   // version
        );
    }

    // Para updateAccount (15 columnas - NO incluye currency)
    public ContractDtos.AccountResponse mapToAccountResponseUpdate(Object[] row, String currency) {
        row = unwrap(row);
        return new ContractDtos.AccountResponse(
            toString(row[0]),     // id
            toString(row[1]),     // userId
            toString(row[2]),     // type (account_type)
            toString(row[3]),     // name
            toString(row[4]),     // institution (bank_name)
            currency,             // currency - del request
            toBigDecimal(row[5]), // balance (1700.75)
            toBigDecimal(row[6]), // creditLimit (24000.00)
            toInteger(row[7]),    // closingDay (null)
            toInteger(row[8]),    // dueDay (null)
            toBoolean(row[9]),    // active (true)
            toInstant(row[10]),   // createdAt
            toInstant(row[11]),   // updatedAt
            toInstant(row[12]),   // deletedAt (null)
            toSyncStatus(row[13]), // syncStatus ("synced")
            toLong(row[14], 1L)   // version (2)
        );
    }


    public ContractDtos.TransactionResponse mapToTransactionResponse(Object[] row) {
    	row = unwrap(row);
        return new ContractDtos.TransactionResponse(
            toString(row[0]), toString(row[1]), toString(row[2]), toString(row[3]),
            toString(row[4]), toString(row[5]), toString(row[6]), toBigDecimal(row[7]),
            toString(row[8]), toLocalDate(row[9]), toString(row[10]),
            toInstant(row[11]), toInstant(row[12]), toInstant(row[13]),
            toSyncStatus(row[14]), toLong(row[15], 1L)
        );

@Component
public class AuthenticatedUser {

    public String getUserId() {
        Authentication authentication = SecurityContextHolder.getContext().getAuthentication();
        if (authentication != null && authentication.getPrincipal() instanceof Jwt jwt) {
            return jwt.getClaimAsString("sub");
        }
        throw new RuntimeException("No authenticated user found");
    }
}

@Service
@Transactional
public class FinanceApiService {

    private final ProfileRepository profileRepo;
    private final CategoryRepository categoryRepo;
    private final AccountRepository accountRepo;
    private final MovementRepository movementRepo;
    private final DebtRepository debtRepo;
    private final ScheduledPaymentRepository scheduledPaymentRepo;
    private final SupabaseAuthClient authClient;
    private final ObjectMapper objectMapper;
    private final FinanceMapper mapper;
    private final JdbcTemplate jdbcTemplate;

    public FinanceApiService(ProfileRepository profileRepo, CategoryRepository categoryRepo,
                            AccountRepository accountRepo, MovementRepository movementRepo,
                            DebtRepository debtRepo, ScheduledPaymentRepository scheduledPaymentRepo,
                            SupabaseAuthClient authClient, ObjectMapper objectMapper, 
                            FinanceMapper mapper,JdbcTemplate jdbcTemplate) {
        this.profileRepo = profileRepo;
        this.categoryRepo = categoryRepo;
        this.accountRepo = accountRepo;
        this.movementRepo = movementRepo;
        this.debtRepo = debtRepo;
        this.scheduledPaymentRepo = scheduledPaymentRepo;
        this.authClient = authClient;
        this.objectMapper = objectMapper;
        this.mapper = mapper;
        this.jdbcTemplate = jdbcTemplate;
    }
    private void setAuthContext(String userId) {
        jdbcTemplate.execute("SELECT set_config('request.jwt.claim.sub', '" + userId + "', true)");
    }

    // ==================== AUTH ====================
    public ContractDtos.AuthResponse signUp(ContractDtos.SignUpRequest request) {
        return authClient.signUp(request);
    }
    public ContractDtos.AuthResponse signIn(ContractDtos.SignInRequest request) {
        return authClient.signIn(request);
    }
    public ContractDtos.SessionResponse refresh(ContractDtos.RefreshRequest request) {
        return authClient.refresh(request);
    }
    public void signOut(String accessToken, ContractDtos.SignOutRequest request) {
        if (accessToken == null || accessToken.isBlank())
            throw new ApiException(HttpStatus.BAD_REQUEST, "Authorization header is required");
        authClient.signOut(accessToken);
    }
    public ContractDtos.SessionResponse session(String accessToken, String refreshToken) {
        return authClient.currentSession(accessToken, refreshToken);
    }

    // ==================== PROFILE ====================
    @Transactional(readOnly = true)
    public ContractDtos.MeResponse getMe(String userId) {
        UUID uuid = UUID.fromString(userId);
        Object[] row = profileRepo.getProfile(uuid);
        if (row == null) throw new ApiException(HttpStatus.NOT_FOUND, "profile not found");
        return mapper.mapToMeResponse(row);
    }

    public ContractDtos.MeResponse updateMe(String userId, ContractDtos.UpdateMeRequest request) {
        UUID uuid = UUID.fromString(userId);
        String payDaysJson = toJson(request.payDays());
        Object[] row = profileRepo.upsertProfile(uuid, request.displayName(), request.currency(),
                                                  request.payCycle(), payDaysJson, uuid);
        return mapper.mapToMeResponse(row);
    }

    // ==================== CATEGORIES ====================
    @Transactional(readOnly = true)
    public List<ContractDtos.CategoryResponse> listCategories(String userId) {
        UUID uuid = UUID.fromString(userId);
        return categoryRepo.listCategories(uuid).stream()
            .map(mapper::mapToCategoryResponse)
            .collect(Collectors.toList());
    }

    public ContractDtos.CategoryResponse createCategory(String userId, ContractDtos.UpsertCategoryRequest request) {
        UUID uuid = UUID.fromString(userId);
        Object[] row = categoryRepo.createCategory(uuid, request.name(), request.color(), request.icon(), request.type());
        return mapper.mapToCategoryResponse(row);
    }

